<script setup lang="ts">import{onBeforeUnmount,onMounted,useTemplateRef}from"vue";import{AlertTriangle}from"lucide-vue-next";const emit=defineEmits<{cancel:[];discard:[]}>();const dialog=useTemplateRef<HTMLElement>("dialog");let previous:HTMLElement|null=null;function keydown(e:KeyboardEvent){if(e.key==="Escape"){e.preventDefault();emit("cancel");return}if(e.key!=="Tab"||!dialog.value)return;const controls=Array.from(dialog.value.querySelectorAll<HTMLButtonElement>("button"));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}onMounted(()=>{previous=document.activeElement instanceof HTMLElement?document.activeElement:null;window.addEventListener("keydown",keydown);requestAnimationFrame(()=>dialog.value?.querySelector<HTMLButtonElement>("[data-cancel]")?.focus())});onBeforeUnmount(()=>{window.removeEventListener("keydown",keydown);previous?.focus()});</script>
<template><Teleport to="body"><div class="fixed inset-0 z-[80] grid place-items-center bg-main-dark/55 p-4" @click.self="emit('cancel')"><section ref="dialog" class="w-full max-w-sm rounded-lg bg-white p-4 shadow-xl" role="alertdialog" aria-modal="true" aria-labelledby="system-unsaved-title"><AlertTriangle class="h-5 w-5 text-warning"/><h2 id="system-unsaved-title" class="mt-2 text-base font-bold">Descartar cambios</h2><p class="mt-1 text-sm text-gray-600">Los cambios escritos no se guardarán.</p><div class="mt-4 grid grid-cols-2 gap-2"><button data-cancel type="button" class="min-h-11 cursor-pointer rounded-md border border-gray-300 text-sm font-semibold" @click="emit('cancel')">Seguir editando</button><button type="button" class="min-h-11 cursor-pointer rounded-md bg-danger px-3 text-sm font-semibold text-white" @click="emit('discard')">Descartar</button></div></section></div></Teleport></template>
